/**
 * R19 — the 144 workspace figures (UXKPI-<ws>-<n>, design contract r19/contract.generated.json) computed from the
 * same permission-scoped adapter records and domain read models every Construction screen uses (domain/data.ts,
 * domain/queues.ts, scheduleCore, cashflow, advances, costVerify, matching, team, inbox). Nothing is stored.
 *
 * A figure whose source the supplied snapshot does not contain is `unavailable` (with the reason) and a figure whose
 * formula needs an owner decision is `pending` — neither is ever shown with an invented number. The demo values in
 * the V4 workbook are design references only and are never used here.
 */
import type { Bi } from "@/lib/dashboards/views";
import type { Doc } from "@/lib/adapter";
import { num, r2, sumBy, validityState } from "../domain/calc";
import { materialMovements } from "../domain/data";
import { contractPosition, contractsOf, costPosition, costSourceRows, financialPosition, get, isSubmitted, list, overdueTasks, procurementOf, resourcesOf, rows, scheduleSlipDays, today, UNALLOCATED, costBuckets, policyDefined, latestForecast, closeoutOf } from "../domain/data";
import { constructionProjects, settings } from "../domain/queues";
import { scheduleKpis, scheduleOf } from "../domain/scheduleCore";
import { cashFlow } from "../domain/cashflow";
import { schedulesOf } from "../domain/advances";
import { costVerification } from "../domain/costVerify";
import { matchingRows } from "../domain/matching";
import { teamOf } from "../domain/teamModel";
import { approvalsFor } from "../domain/inbox";
