import { overrunLines, revisionDeltas, useLevel, usedPct } from "../domain/costScreens";

export type Filt = [string, string, unknown];
export type CDrill = { kind: "list"; doctype: string; filters?: Filt[] | undefined } | { kind: "doc"; doctype: string; name: string } | { kind: "report"; report: string; filters?: Record<string, string> | undefined } | { kind: "page"; to: string };
export type Unit = "count" | "money" | "pct" | "days" | "hours" | "qty";
/** `ar`: screen language, used only for fixed words inside composed chart cells (never for stored values). */
export interface Scope { company?: string | undefined; project?: string | undefined; on: string; ar?: boolean | undefined }
/** `unconfigured`: waits for a setting nobody entered (shown with the setting); `quality`: a shown figure that is partial or stale, with why. */
/** `meter`: progress against a budget drawn under the value (phase 5: no number-only cost card), share in %, level from the budget settings. */
export interface Fig { value: number | null; unit: Unit; drill?: CDrill | undefined; status?: "ok" | "unavailable" | "pending" | "unconfigured" | undefined; reason?: Bi | undefined; sub?: Bi | undefined; quality?: "partial" | "stale" | undefined; qualityNote?: Bi | undefined; meter?: { pct: number; level?: "ok" | "warn" | "over" | undefined; label: Bi } | undefined }
export interface KpiDef { id: string; ws: string; title: Bi; sources: string[]; formula: Bi; fig: (s: Scope) => Fig }

/* ------------------------------------------------------------------ scope helpers ------------------------------------------------------------------ */
export const projectsOf = (s: Scope) => constructionProjects({ company: s.company, project: s.project });
const pset = (s: Scope) => new Set(projectsOf(s).map((p) => p.name));
/** Project-linked records in scope; records without a project follow the company filter (when the record has a company). */
export function docs(dt: string, s: Scope, pred: (d: Doc) => boolean = () => true): Doc[] {
  const ps = pset(s);
  return list(dt, (d) => {
    if (num(d.docstatus) === 2) return false;
    if ("project" in d && d["project"]) { if (!ps.has(String(d["project"]))) return false; }
    else if (s.project && "project" in d) return false;
    else if (s.company && d["company"] && d["company"] !== s.company) return false;
    return pred(d);
  });
}
const day = (v: unknown) => String(v ?? "").slice(0, 10);
const monthOf = (s: Scope) => s.on.slice(0, 7);
const inMonth = (v: unknown, s: Scope) => day(v).slice(0, 7) === monthOf(s);
const addDays = (d: string, n: number) => new Date(Date.parse(`${d}T00:00:00Z`) + n * 86400000).toISOString().slice(0, 10);
const ageOf = (v: unknown, on: string) => { const d = day(v); return d ? Math.max(0, Math.round((Date.parse(on) - Date.parse(d)) / 86400000)) : 0; };
const list_ = (doctype: string, filters?: Filt[]): CDrill => ({ kind: "list", doctype, ...(filters ? { filters } : {}) });
const rep = (report: string, s?: Scope, extra: Record<string, string> = {}): CDrill => ({ kind: "report", report, filters: { ...(s?.company ? { company: s.company } : {}), ...(s?.project ? { project: s.project } : {}), ...extra } });
const page = (to: string): CDrill => ({ kind: "page", to });
const n = (value: number | null, unit: Unit, drill?: CDrill, sub?: Bi): Fig => ({ value, unit, ...(drill ? { drill } : {}), ...(sub ? { sub } : {}) });
const NA = (unit: Unit, reason: Bi): Fig => ({ value: null, unit, status: "unavailable", reason });
const PENDING = (unit: Unit, reason: Bi): Fig => ({ value: null, unit, status: "pending", reason });
const pctOf = (a: number, b: number) => (b ? r2((a / b) * 100) : null);
/** A figure with its progress against a budget (share used, level from the budget settings) — phase 5 cost cards. */
const withMeter = (f: Fig, used: number, budget: number, words: Bi): Fig => { const p = usedPct(used, budget); if (p === null) return f; const lv = useLevel(used, budget); return { ...f, meter: { pct: p, level: lv === "none" ? undefined : lv, label: [`${p}% ${words[0]}`, `${p}% ${words[1]}`] } }; };
const NO_SOURCE = (what: string, whatAr: string): Bi => [`The supplied source has no ${what}; this figure stays empty until that record exists.`, `لا يحتوي المصدر المورد على ${whatAr}؛ يبقى هذا الرقم فارغًا حتى يوجد ذلك السجل.`];
const OWNER = (what: string, whatAr: string): Bi => [`Needs an owner decision: ${what}.`, `يحتاج قرار المالك: ${whatAr}.`];

const RISK_OPEN = ["Proposed", "Open", "Active"];
const DEFECT_OPEN = ["Open", "In Progress", "Ready to Inspect"];
// K04-01: the same open set as the register's «Open Only» drill (reportsR19.ts CLAIM_OPEN)
const contractsIn = (s: Scope) => { const ps = pset(s); return contractsOf().filter((c) => ps.has(String(c["project"])) && c["workflow_state"] !== "Draft" && num(c.docstatus) !== 2); };
const positions = (s: Scope) => contractsIn(s).map((c) => ({ c, p: contractPosition(c) }));
const costs = (s: Scope) => projectsOf(s).map((p) => ({ p, c: costPosition(p.name, s.on) }));
const sumP = (xs: { p: ReturnType<typeof contractPosition> }[], k: keyof ReturnType<typeof contractPosition>) => sumBy(xs, (x) => num(x.p[k]));

/* ------------------------------------------------------------------ the 144 figures ------------------------------------------------------------------ */
const K = (ws: string, i: number, title: Bi, sources: string[], formula: Bi, fig: (s: Scope) => Fig): KpiDef => ({ id: `UXKPI-${ws}-0${i}`, ws, title, sources, formula, fig });

