/* ------------------------------------------------------------------ helpers used above ------------------------------------------------------------------ */
/** Research-question best practice as changeable Construction Settings (fallback applies while the setting is empty). */
const slaDays = () => num(settings()?.["approval_sla_days"]) || 3;
const slowDays = () => num(settings()?.["slow_moving_days"]) || 90;
const availHours = () => num(settings()?.["machine_available_hours"]) || 8;
const savingBasis = () => String(settings()?.["award_saving_basis"] || "Average bid");
const SAVING_BASIS_AR: Record<string, string> = { "Average bid": "متوسط العروض", "Second lowest bid": "ثاني أقل عرض", Budget: "موازنة الحزمة" };
/** Saving of one award against the basis; null when the awarded bid or the basis is unknown. */
export function awardSaving(lev: Doc, pkg: Doc, basis: string): number | null {
  const bids = list("Digit Subcontract Bid", (b) => b["bid_package"] === lev["bid_package"]).map((b) => ({ supplier: String(b["supplier"] ?? ""), total: num(b["base_total"]) || num(b["total"]) })).filter((b) => b.total > 0);
  const won = bids.find((b) => b.supplier === String(lev["awarded_supplier"] ?? "")); if (!won) return null;
  const sorted = bids.map((b) => b.total).sort((a, b) => a - b);
  const base = basis === "Budget" ? num(pkg["amount"]) || null : basis === "Second lowest bid" ? (sorted.length > 1 ? sorted[1]! : null) : sorted.length ? sumBy(sorted, (x) => x) / sorted.length : null;
  return base === null ? null : r2(base - won.total);
}
/** Item + warehouse positions of the project's vouchers with stock on hand and no movement for `days` up to `on`. */
export function slowMoving(project: string, on: string, days: number): number {
  const by = new Map<string, { qty: number; last: string }>();
  for (const m of materialMovements(project, on)) { const k = `${m.item_code}|${m.warehouse}`; const x = by.get(k) ?? { qty: 0, last: "" }; x.qty += m.qty; if (m.posting_date > x.last) x.last = m.posting_date; by.set(k, x); }
  const cut = addDays(on, -days); let c = 0; for (const x of by.values()) if (x.qty > 1e-9 && x.last && x.last.slice(0, 10) < cut) c++; return c;
}
function weighted(ts: { start: string; end: string; progress: number }[]) {
  let w = 0, sm = 0;
  for (const t of ts) { const d = Math.max(1, Math.round((Date.parse(t.end) - Date.parse(t.start)) / 86400000) + 1); w += d; sm += d * t.progress; }
  return w ? Math.round((sm / w) * 10) / 10 : 0;
}
export function plannedAt(t: { start: string; end: string }, on: string) { if (on < t.start) return 0; if (on >= t.end) return 100; const dur = Math.round((Date.parse(t.end) - Date.parse(t.start)) / 86400000) + 1; return Math.round(((Math.round((Date.parse(on) - Date.parse(t.start)) / 86400000) + 1) / dur) * 1000) / 10; }
const warnDays = () => num(settings()?.["rate_expiry_warning_days"]) || 30;
const rates = (_s: Scope) => list("Digit Construction Rate", (r) => !num(r["disabled"]));
const EST_OPEN = ["Draft", "Submitted", "Returned"];
const estimates = (s: Scope) => list("Digit Estimate Version", (d) => EST_OPEN.includes(String(d["workflow_state"] || "Draft")) && num(d.docstatus) !== 2 && (!s.company || !d["company"] || d["company"] === s.company) && (!s.project || d["project"] === s.project));
const TENDER_DONE = ["Won", "Lost", "Cancelled"];
const tenders = (s: Scope) => list("Digit Tender", (t) => (!s.company || t["company"] === s.company) && (!s.project || t["project"] === s.project));
const openTenders = (s: Scope) => tenders(s).filter((t) => !TENDER_DONE.includes(String(t["status"])));
const activeWos = (s: Scope) => docs("Digit Subcontract Work Order", s, (w) => w["workflow_state"] === "Active");
const procs = (s: Scope) => projectsOf(s).map((p) => procurementOf(p.name, s.on));
const machines = (s: Scope) => list("Digit Machinery", (m) => (!s.company || !m["company"] || m["company"] === s.company) && (!s.project || m["current_project"] === s.project));
export const resources = (s: Scope) => projectsOf(s).map((p) => resourcesOf(p.name));

/** Rows of a construction report for the scope (project-required reports run once per readable project). */
export function reportRows(name: string, s: Scope): Record<string, unknown>[] {
  const r = CONSTRUCTION_REPORTS.find((x) => x.name === name); if (!r?.run) return [];
  const needsProject = (r.filters ?? []).some((f) => f.fieldname === "project" && (f as { reqd?: number }).reqd);
  const base = { ...(s.company ? { company: s.company } : {}) };
  try {
    if (!needsProject) return r.run({ ...base, ...(s.project ? { project: s.project } : {}) }).filter((x) => !x["is_total"]);
    return projectsOf(s).flatMap((p) => r.run!({ ...base, project: p.name })).filter((x) => !x["is_total"]);
  } catch { return []; }
}
const reportRowsCount = (name: string, s: Scope, pred: (r: Record<string, unknown>) => boolean) => reportRows(name, s).filter(pred).length;

export const kpisOf = (ws: string) => KPIS.filter((k) => k.ws === ws);

